mapper.select:
SELECT TP.PUB_ID , TP.PUB_TITLE , TP.PUB_SUB_TITLE , TP.PUB_VOLUME , TP.PUB_YEAR , TP.PUB_TYPE , TP.USE_YN , TP.DISPLAY_ORDER , TP.REG_DT , TP.REG_ID , TP.PUB_THUMB_FILE_ID , TP.PUB_PDF_FILE_ID , ( SELECT SAVE_FILE_NAME FROM ATCH_FILE AF WHERE AF.DELETE_YN = 'N' AND AF.ATCH_FILE_IDX = TP.PUB_THUMB_FILE_ID LIMIT 1 ) AS THUMB_FILE_NAME , ( SELECT ORG_FILE_NAME FROM ATCH_FILE AF WHERE AF.DELETE_YN = 'N' AND AF.ATCH_FILE_IDX = TP.PUB_THUMB_FILE_ID LIMIT 1 ) AS THUMB_ORG_FILE_NAME , ( SELECT ORG_FILE_NAME FROM ATCH_FILE AF WHERE AF.DELETE_YN = 'N' AND AF.ATCH_FILE_IDX = TP.PUB_PDF_FILE_ID LIMIT 1 ) AS PDF_ORG_FILE_NAME
FROM TB_PUBLICATION TP WHERE TP.DELETE_YN = 'N'
AND TP.PUB_TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
AND TP.PUB_YEAR = #{searchYear}
AND TP.PUB_TYPE = #{searchType}
ORDER BY TP.DISPLAY_ORDER DESC
LIMIT #{firstIndex}, #{recordCountPerPage}

mapper.insert:
INSERT INTO TB_PUBLICATION (
      PUB_ID
    , PUB_TITLE
    , PUB_SUB_TITLE
    , PUB_VOLUME
    , PUB_YEAR
    , PUB_TYPE
    , PUB_THUMB_FILE_ID
    , PUB_PDF_FILE_ID
    , BUY_URL
    , DISPLAY_ORDER
    , USE_YN
    , DELETE_YN
    , REG_ID
    , REG_DT
)
VALUES (
	  #{pubId}
    , #{pubTitle}
    , #{pubSubTitle}
    , #{pubVolume}
    , #{pubYear}
    , #{pubType}
    , #{pubThumbFileId}
    , #{pubPdfFileId}
    , #{buyUrl}
    , #{displayOrder}
    , #{useYn}
    , 'N'
    , #{sessionMemId}
    , NOW()
)

mapper.update:
UPDATE TB_PUBLICATION
   SET PUB_TITLE = #{pubTitle}
     , PUB_SUB_TITLE = #{pubSubTitle}
     , PUB_VOLUME = #{pubVolume}
     , PUB_YEAR = #{pubYear}
     , PUB_TYPE = #{pubType}

     , PUB_THUMB_FILE_ID = #{pubThumbFileId}


     , PUB_PDF_FILE_ID = #{pubPdfFileId}

     , BUY_URL = #{buyUrl}
     , DISPLAY_ORDER = #{displayOrder}
     , USE_YN = #{useYn}
     , UPD_ID = #{sessionMemId}
     , UPD_DT = NOW()
 WHERE PUB_ID = #{pubId}

UPDATE TB_PUBLICATION
   SET DELETE_YN = 'Y'
     , UPD_ID = #{sessionMemId}
     , UPD_DT = NOW()
 WHERE PUB_ID = #{pubId}

